import{_ as t,o,c as a,ag as r}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Frameworks and resources","description":"","frontmatter":{},"headers":[],"relativePath":"bridge/index.md","filePath":"bridge/index.md"}'),n={name:"bridge/index.md"};function s(d,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="frameworks-and-resources" tabindex="-1">Frameworks and resources <a class="header-anchor" href="#frameworks-and-resources" aria-label="Permalink to &quot;Frameworks and resources&quot;">​</a></h1><p>Every Nayretis script talks to your server through the <code>nay_lib</code> bridge. It detects your framework, inventory, target and notifications the first time it is used, so the same script runs on every supported stack.</p><h2 id="supported-stacks" tabindex="-1">Supported stacks <a class="header-anchor" href="#supported-stacks" aria-label="Permalink to &quot;Supported stacks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Adapters</th><th>Fallback</th></tr></thead><tbody><tr><td>Framework</td><td><code>qbox</code> (qbx_core), <code>ox</code> (ox_core), <code>esx</code> (es_extended), <code>qbcore</code> (qb-core), <code>custom</code></td><td>none, the script stops with an error</td></tr><tr><td>Inventory</td><td><code>ox_inventory</code>, <code>qs-inventory</code>, <code>qb-inventory</code></td><td><code>framework</code> (the framework&#39;s own inventory)</td></tr><tr><td>Target</td><td><code>ox_target</code>, <code>qb-target</code></td><td><code>none</code> (key prompts)</td></tr><tr><td>Notifications</td><td><code>ox_lib</code>, <code>nayretis</code> (only when forced)</td><td><code>framework</code>, then <code>native</code> (GTA feed)</td></tr></tbody></table><p>Detection follows the order of the table. Start <code>nay_lib</code> <strong>after</strong> your framework, inventory and target resources, otherwise they cannot be detected.</p><h2 id="force-an-adapter" tabindex="-1">Force an adapter <a class="header-anchor" href="#force-an-adapter" aria-label="Permalink to &quot;Force an adapter&quot;">​</a></h2><p>If detection picks the wrong resource, force it in <code>server.cfg</code> with <code>setr</code> (the client reads it too):</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setr nay:framework &quot;esx&quot;</span></span>
<span class="line"><span>setr nay:inventory &quot;ox_inventory&quot;</span></span>
<span class="line"><span>setr nay:target &quot;ox_target&quot;</span></span>
<span class="line"><span>setr nay:notify &quot;native&quot;</span></span></code></pre></div><p>Values are the adapter names above, or <code>auto</code> (the default). See <a href="/nay-lib/convars">Convars</a>.</p><p>Running a framework that is not in the list? Write a <a href="/bridge/custom">custom adapter</a>.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li><strong>ox_core</strong>: there is no duty flag, so the active group is treated as the on-duty job. The highest grade of a group counts as boss.</li><li><strong>ox_inventory</strong> (any framework): usable items must exist in <code>ox_inventory/data/items.lua</code>. ox_inventory only calls the item callback for items without <code>consume</code>, <code>client.export</code> or <code>server.export</code>.</li><li><strong>qb-inventory</strong>: item metadata is ignored when counting items.</li><li><strong>qs-inventory</strong>: the results of adding and removing items are undocumented. Any result other than <code>false</code> is treated as a success.</li><li><strong>ESX</strong>: notifications use <code>esx_notify</code> when it is started, the GTA feed otherwise.</li></ul>`,12)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
